<p class="eyebrow">Account settings</p><h1>Security</h1><?php if($recoveryCodes): ?><section class="card recovery"><h2>Save your recovery codes</h2><p>These codes are shown once. Store them in a secure password manager or offline location.</p><div class="recovery-codes"><?php foreach($recoveryCodes as $code): ?><code><?= e($code) ?></code><?php endforeach; ?></div></section><?php endif; ?><div class="grid two dashboard-split"><section class="card"><h2>Password</h2><form method="post" action="<?= e(route('dashboard.security.password')) ?>" class="form-stack"><?= app('csrf')->input() ?><label class="field">Current password<input type="password" name="current_password" required></label><label class="field">New password<input type="password" name="password" minlength="8" required></label><label class="field">Confirm new password<input type="password" name="password_confirmation" minlength="8" required></label><button class="button" type="submit">Change password</button></form></section><section class="card"><h2>Email verification</h2><p><?= !empty($user['email_verified_at'])?'Your email address is verified.':($verificationRequired?'Email verification is required for sensitive account activity.':'Email verification is currently optional.') ?></p><?php if(empty($user['email_verified_at'])): ?><form method="post" action="<?= e(route('dashboard.security.resend-verification')) ?>"><?= app('csrf')->input() ?><button class="button button-secondary" type="submit">Resend verification email</button></form><?php endif; ?><hr><h2>Authenticator app</h2><?php if(empty($user['two_factor_enabled_at'])): ?><a class="button" href="<?= e(route('dashboard.two-factor.setup')) ?>">Enable two-factor authentication</a><?php else: ?><p>Two-factor authentication is enabled.</p><form method="post" action="<?= e(route('dashboard.two-factor.disable')) ?>" class="form-stack"><?= app('csrf')->input() ?><label class="field">Authenticator code<input name="code" inputmode="numeric" required></label><button class="button button-danger" type="submit">Disable two-factor authentication</button></form><form method="post" action="<?= e(route('dashboard.two-factor.regenerate')) ?>" class="form-stack compact"><?= app('csrf')->input() ?><label class="field">Authenticator code<input name="code" inputmode="numeric" required></label><button class="button button-secondary" type="submit">Regenerate recovery codes</button></form><?php endif; ?></section></div><section class="card"><h2>Active sessions</h2><form method="post" action="<?= e(route('dashboard.security.sessions.revoke-others')) ?>" class="inline-form"><?= app('csrf')->input() ?><button class="button button-secondary" type="submit">Sign out other sessions</button></form><div class="table-wrap"><table><thead><tr><th>Device</th><th>IP</th><th>Last active</th><th></th></tr></thead><tbody><?php foreach($sessions as $session): ?><tr><td><?= e($session['device_label']??'Unknown device') ?><?= hash_equals((string)($session['session_hash']??''),(string)($_SESSION['auth_session_hash']??''))?' (current)':'' ?></td><td><?= e($session['ip_address']??'') ?></td><td><?= e($session['last_active_at']) ?></td><td><?php if(!hash_equals((string)($session['session_hash']??''),(string)($_SESSION['auth_session_hash']??''))): ?><form method="post" action="<?= e(route('dashboard.security.session.revoke',['session'=>$session['id']])) ?>"><?= app('csrf')->input() ?><button class="text-button" type="submit">Revoke</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="card"><h2>Recent security activity</h2><div class="table-wrap"><table><thead><tr><th>Event</th><th>When</th><th>IP</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= e(str_replace('_',' ',ucwords($event['event_type'],'_'))) ?></td><td><?= e($event['created_at']) ?></td><td><?= e($event['ip_address']??'') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
